/* ===============================================
   SABAN REALTY - JavaScript
   =============================================== */

document.addEventListener('DOMContentLoaded', function() {
  
  // ---- Mobile Navigation ----
  const navToggle = document.querySelector('.nav-toggle');
  const navMenu = document.querySelector('.nav-menu');
  const navClose = document.querySelector('.nav-close');
  const navLinks = document.querySelectorAll('.nav-link');

  if (navToggle) {
    navToggle.addEventListener('click', () => {
      navMenu.classList.add('active');
      document.body.style.overflow = 'hidden';
    });
  }

  if (navClose) {
    navClose.addEventListener('click', () => {
      navMenu.classList.remove('active');
      document.body.style.overflow = '';
    });
  }

  navLinks.forEach(link => {
    link.addEventListener('click', () => {
      navMenu.classList.remove('active');
      document.body.style.overflow = '';
    });
  });

  // ---- Navbar Scroll Effect ----
  const navbar = document.querySelector('.navbar');
  // If the HTML already marks this navbar as scrolled (inner pages), lock it solid.
  const navbarAlwaysSolid = navbar && navbar.classList.contains('scrolled');

  function handleNavbarScroll() {
    if (navbarAlwaysSolid) return; // Inner pages stay solid always
    if (window.scrollY > 100) {
      navbar.classList.add('scrolled');
    } else {
      navbar.classList.remove('scrolled');
    }
  }

  window.addEventListener('scroll', handleNavbarScroll);
  handleNavbarScroll(); // Run on page load

  // ---- Scroll to Top Button ----
  const scrollTopBtn = document.querySelector('.scroll-top');
  
  if (scrollTopBtn) {
    window.addEventListener('scroll', () => {
      if (window.scrollY > 500) {
        scrollTopBtn.classList.add('active');
      } else {
        scrollTopBtn.classList.remove('active');
      }
    });

    scrollTopBtn.addEventListener('click', () => {
      window.scrollTo({
        top: 0,
        behavior: 'smooth'
      });
    });
  }

  // ---- Smooth Scroll for Anchor Links ----
  document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function(e) {
      const target = document.querySelector(this.getAttribute('href'));
      if (target) {
        e.preventDefault();
        const offsetTop = target.offsetTop - 80; // Account for fixed navbar
        window.scrollTo({
          top: offsetTop,
          behavior: 'smooth'
        });
      }
    });
  });

  // ---- Fade In Animation on Scroll ----
  const fadeElements = document.querySelectorAll('.fade-in');
  
  const fadeInObserver = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        fadeInObserver.unobserve(entry.target);
      }
    });
  }, {
    threshold: 0.1,
    rootMargin: '0px 0px -50px 0px'
  });

  fadeElements.forEach(el => fadeInObserver.observe(el));

  // (Property filtering is handled per-page by inline scripts on index/buy/rent —
  //  each page's filter has island/village logic this shared file never knew about.)

  // ---- Form Validation ----
  const forms = document.querySelectorAll('form[data-validate]');
  
  forms.forEach(form => {
    form.addEventListener('submit', function(e) {
      e.preventDefault();
      
      let isValid = true;
      const requiredFields = form.querySelectorAll('[required]');
      
      requiredFields.forEach(field => {
        removeError(field);
        
        if (!field.value.trim()) {
          showError(field, 'This field is required');
          isValid = false;
        } else if (field.type === 'email' && !isValidEmail(field.value)) {
          showError(field, 'Please enter a valid email address');
          isValid = false;
        } else if (field.type === 'tel' && !isValidPhone(field.value)) {
          showError(field, 'Please enter a valid phone number');
          isValid = false;
        }
      });
      
      if (isValid) {
        // Show success message
        showFormSuccess(form);
        form.reset();
      }
    });
  });

  function showError(field, message) {
    field.classList.add('error');
    const errorEl = document.createElement('span');
    errorEl.className = 'error-message';
    errorEl.textContent = message;
    errorEl.style.cssText = 'color: #e07a5f; font-size: 0.875rem; margin-top: 0.25rem; display: block;';
    field.parentNode.appendChild(errorEl);
  }

  function removeError(field) {
    field.classList.remove('error');
    const errorEl = field.parentNode.querySelector('.error-message');
    if (errorEl) errorEl.remove();
  }

  function isValidEmail(email) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
  }

  function isValidPhone(phone) {
    return /^[\d\s\-\+\(\)]{10,}$/.test(phone);
  }

  function showFormSuccess(form) {
    const successMsg = document.createElement('div');
    successMsg.className = 'form-success';
    successMsg.innerHTML = `
      <div style="background: #27ae60; color: white; padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: center;">
        <strong>Thank you!</strong> Your message has been sent successfully. We'll get back to you soon.
      </div>
    `;
    form.appendChild(successMsg);

    setTimeout(() => {
      successMsg.remove();
    }, 5000);
  }

  function showFormError(form) {
    const existing = form.querySelector('.form-error');
    if (existing) existing.remove();

    const errorMsg = document.createElement('div');
    errorMsg.className = 'form-error';
    errorMsg.innerHTML = `
      <div style="background: #e07a5f; color: white; padding: 1rem; border-radius: 8px; margin-top: 1rem; text-align: center;">
        <strong>Something went wrong.</strong> Please try again or email us directly at jeffsabarealty@gmail.com
      </div>
    `;
    form.appendChild(errorMsg);

    setTimeout(() => {
      errorMsg.remove();
    }, 7000);
  }

  // ---- Contact Form (FormSubmit.co AJAX) ----
  const contactForm = document.getElementById('contactForm');

  if (contactForm) {
    contactForm.addEventListener('submit', async function(e) {
      e.preventDefault();

      // Client-side validation
      let isValid = true;
      const requiredFields = contactForm.querySelectorAll('[required]');

      requiredFields.forEach(field => {
        removeError(field);
        if (!field.value.trim()) {
          showError(field, 'This field is required');
          isValid = false;
        } else if (field.type === 'email' && !isValidEmail(field.value)) {
          showError(field, 'Please enter a valid email address');
          isValid = false;
        }
      });

      if (!isValid) return;

      const submitBtn = contactForm.querySelector('button[type="submit"]');
      const originalText = submitBtn.textContent;
      submitBtn.textContent = 'Sending...';
      submitBtn.disabled = true;

      try {
        const formData = new FormData(contactForm);
        const response = await fetch('https://formsubmit.co/ajax/jeffsabarealty@gmail.com', {
          method: 'POST',
          body: formData
        });
        const result = await response.json();

        if (result.success) {
          showFormSuccess(contactForm);
          contactForm.reset();
        } else {
          showFormError(contactForm);
        }
      } catch (error) {
        showFormError(contactForm);
      } finally {
        submitBtn.textContent = originalText;
        submitBtn.disabled = false;
      }
    });
  }

  // ---- Newsletter Form (FormSubmit.co AJAX) ----
  const newsletterForm = document.querySelector('.newsletter-form');

  if (newsletterForm) {
    newsletterForm.addEventListener('submit', async function(e) {
      e.preventDefault();
      const email = this.querySelector('input[type="email"]');

      if (!email || !isValidEmail(email.value)) return;

      const submitBtn = this.querySelector('button[type="submit"]');
      const originalText = submitBtn.textContent;
      submitBtn.textContent = 'Subscribing...';
      submitBtn.disabled = true;

      try {
        const formData = new FormData();
        formData.append('email', email.value);
        formData.append('_subject', 'New Newsletter Subscriber - Saban Realty');
        formData.append('_template', 'table');

        const response = await fetch('https://formsubmit.co/ajax/jeffsabarealty@gmail.com', {
          method: 'POST',
          body: formData
        });
        const result = await response.json();

        if (result.success) {
          this.innerHTML = '<p style="color: #27ae60; font-weight: 600;">Thank you for subscribing!</p>';
        } else {
          submitBtn.textContent = originalText;
          submitBtn.disabled = false;
          showFormError(this);
        }
      } catch (error) {
        submitBtn.textContent = originalText;
        submitBtn.disabled = false;
        showFormError(this);
      }
    });
  }

  // ---- Active Navigation Link ----
  const currentPage = window.location.pathname.split('/').pop() || 'index.html';
  const navLinksAll = document.querySelectorAll('.nav-link');
  
  navLinksAll.forEach(link => {
    const href = link.getAttribute('href');
    if (href === currentPage || (currentPage === '' && href === 'index.html')) {
      link.classList.add('active');
    }
  });

});
